import sys


def search(a, b):
    # 두 문자열 모두 비면 0, 한쪽만 비면 남은 길이만큼 삽입 또는 삭제
    if not a:
        return len(b)
    if not b:
        return len(a)
    # 마지막 글자를 두고 가능한 모든 선택을 다 해 본다
    options = [
        search(a[:-1], b) + 1,
        search(a, b[:-1]) + 1,
        search(a[:-1], b[:-1]) + (0 if a[-1] == b[-1] else 1),
    ]
    return min(options)


def main():
    data = sys.stdin.read().split()
    print(search(data[0], data[1]))


main()

