import sys


def solve(a, b, i, j):
    if i == len(a):
        return len(b) - j
    if j == len(b):
        return len(a) - i
    if a[i] == b[j]:
        return solve(a, b, i + 1, j + 1)
    return 1 + min(
        solve(a, b, i + 1, j + 1),
        solve(a, b, i + 1, j),
        solve(a, b, i, j + 1),
    )


def main():
    sys.setrecursionlimit(10000)
    data = sys.stdin.read().split()
    print(solve(data[0], data[1], 0, 0))


main()
